parameters.jsCode:
/**
 * Erstellt aus einer eingehenden E-Mail einen strukturierten Gemini-Prompt.
 *
 * @returns {Array<{json: object}>} Normalisierte E-Mail-Daten und KI-Prompt
 */
const email = $input.first().json;
const values = Object.values(email);

const senderRaw = String(
  email.sender ??
  email.Sender ??
  email.Absender ??
  email.From ??
  email.from ??
  values[0] ??
  ""
).trim();

const emailMatch =
  senderRaw.match(/<([^<>@]+@[^<>]+)>/) ||
  senderRaw.match(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/);

const senderEmail = emailMatch
  ? String(emailMatch[1] || emailMatch[0]).trim()
  : senderRaw;

const creatorName = senderRaw
  .replace(/<[^<>]+>/g, "")
  .replace(senderEmail, "")
  .replace(/^["']|["']$/g, "")
  .trim();

const subject = String(
  email.subject ??
  email.Subject ??
  email.Subjekt ??
  email.Betreff ??
  values[1] ??
  ""
).trim();

const body = String(
  email.body ??
  email.Body ??
  email.Körper ??
  email.Nachricht ??
  email.textPlain ??
  email.text ??
  email.snippet ??
  values[2] ??
  ""
).trim();

/**
 * Ermittelt das aktuelle Datum in der Zeitzone Europe/Zurich.
 */
const currentDate = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Europe/Zurich",
  day: "2-digit",
  month: "2-digit",
  year: "numeric"
}).format(new Date());

const aiPrompt = `
Analysiere die folgende E-Mail und antworte ausschließlich mit gültigem JSON.

Das heutige Datum ist: ${currentDate}

Erforderliches Format:
{
  "title": "Kurzer prägnanter Titel",
  "description": "Bereinigte Ticketbeschreibung ohne Subtasks",
  "category": "Bug oder User Story oder Technical Task",
  "priority": "urgent oder medium oder low",
  "deadline": "DD/MM/YYYY oder null",
  "subtasks": [
    "Erster Subtask",
    "Zweiter Subtask"
  ]
}

Regeln:
- Kategorie muss Bug, User Story oder Technical Task sein.
- Priorität muss urgent, medium oder low sein.
- Übernimm eine Deadline nur, wenn sie in der E-Mail genannt wurde.
- Erfinde keine Deadline.
- Eine Deadline darf nicht in der Vergangenheit liegen.
- Korrigiere eine ungültige oder vergangene Deadline auf ${currentDate}.
- Verwende für Deadlines ausschließlich DD/MM/YYYY.
- Extrahiere alle genannten Subtasks vollständig.
- Jeder Subtask muss ein eigener Eintrag im Array sein.
- Schreibe Subtasks nicht zusätzlich in die Beschreibung.
- Wenn keine Subtasks genannt wurden, verwende [].
- Die Beschreibung darf nur die eigentliche Anfrage enthalten.
- Antworte ohne Markdown und ausschließlich mit dem JSON-Objekt.

Absendername: ${creatorName || "Nicht angegeben"}
Absender-E-Mail: ${senderEmail}
Betreff: ${subject}
Nachricht: ${body}
`;

return [
  {
    json: {
      sender: senderEmail,
      senderEmail,
      senderRaw,
      creatorName,
      subject,
      body,
      aiPrompt
    }
  }
];
